INSERT INTO `products` VALUES (3,NULL,NULL,'لابتوب دل','Dell',1,'معالج 7',NULL,'مم',300000.00,NULL,NULL,145,0,'active','products/3g3JdSezCtlHoL90WufQdZY9oFvtR1TaJusemr2g.jpg',NULL,NULL,1,1,NULL,NULL,'2026-01-07 17:44:42','2026-03-29 17:44:20','USD',NULL,NULL,NULL),(4,'PRD-001',NULL,'منتج جديد اولي','Apple',2,'جهاز لاب توب ابل MLHF2B/A ماك بوك - انتل كور 1.2جيجاهيرتز M5 ثنائي النواة، 12انش، 512جيجا،','لايوجد','جهاز لاب توب ابل MLHF2B/A ماك بوك - انتل كور 1.2جيجاهيرتز M5 ثنائي النواة، 12انش، 512جيجا، 8جيجا، نظام التشغيل X E1 كابتن، ذهبي، اصدار عالمي',2000.00,0.00,0.00,0,5,'active','products/2SSNcfnsLqV6sTy3hKAN1ZfW88yfxwoV4xRCos7K.jpg',NULL,NULL,2,1,NULL,NULL,'2026-01-16 19:26:03','2026-03-29 17:44:20','YER',NULL,NULL,NULL),(5,'FX608ZV',NULL,'ASUS TUF Gaming F16','Asus',3,'المعالج: Intel Core i7-14650HX (أداء خارق).\r\n\r\nكرت الشاشة: NVIDIA RTX 5060 8GB GDDR7 (أحدث جيل).\r\n\r\nالذاكرة: 32GB DDR5 RAM (سرعة فائقة).\r\n\r\nالتخزين: 1TB SSD NVMe.\r\n\r\nالشاشة: 16\" WUXGA 165Hz (تجربة بصرية مذهلة).\r\n\r\nالحالة: جديد كلياً (مختم) مع ضمان لمدة سنة.','البصمات: هيكل الـ TUF الجديد (Mecha Gray) فخم جداً ولكنه يطبع بصمات الأصابع بسهولة. انصح الزبون بمسحه بقطعة قماش ناعمة للحفاظ على مظهره الجديد.','اقتنِ القوة المطلقة مع الإصدار الأحدث من سلسلة ASUS TUF Gaming لعام 2025. صُمم هذا الجهاز ليتحدى أصعب الألعاب وبرامج التصميم الهندسي والمونتاج، بفضل الجمع بين معالج إنتل من فئة HX وكرت الشاشة الثوري من الجيل الخمسين.',1590.00,NULL,NULL,15,5,'active','products/KscL4myul9z2kVlqDGKd1KNFl0Snpc1L6C6pmHQW.jpg',NULL,NULL,3,1,NULL,NULL,'2026-02-15 19:54:41','2026-03-29 17:44:20','USD',NULL,NULL,NULL),(6,'FX608-5060',NULL,'Lenovo Legion 5','Lenovo',4,'لابتوب ASUS TUF F16 موديل 2025: معالج i7-14650HX، كرت RTX 5060 الجديد، رام 32GB، وشاشة 16 بوصة 165Hz. أداء جبار للمستقبل','يفضل استخدامه على سطح مستوٍ لضمان أفضل تبريد لمعالج فئة HX','استمتع بأحدث تقنيات الألعاب مع ASUS TUF Gaming F16 (2025). الجهاز مزود بمعالج Intel Core i7-14650HX عالي الأداء وكرت الشاشة الثوري NVIDIA RTX 5060 بذاكرة GDDR7 الأسرع عالمياً. مع رام 32GB وشاشة 165Hz، يمنحك الجهاز سلاسة فائقة في أثقل الألعاب وبرامج المونتاج والهندسة. تصميم متين بمعايير عسكرية ونظام تبريد مطور',1950.00,NULL,NULL,12,5,'active','products/6ymRfCNRhRpiWOSAgp8jO7zaoKQvA5bMdRayrF32.jpg',NULL,NULL,3,1,NULL,NULL,'2026-02-15 20:04:39','2026-03-29 17:44:20','USD',NULL,NULL,NULL),(7,'GM-RGB',NULL,'Gaming Mouse RGB','Asus',3,'فأرة ألعاب احترافية عالية الدقة، مصممة لتوفير استجابة سريعة وتحكم فائق. تتميز بإضاءة RGB جذابة وتصميم مريح يناسب جلسات اللعب الطويلة.','صُممت بوزن متوازن يوفر ثباتاً عالياً أثناء الحركة السريعة لمنع الانزلاق المفاجئ.','مستشعر دقيق: يمنحك تتبعاً دقيقاً لحركاتك لضمان التفوق في ألعاب القنص والسرعة.\r\n\r\nإضاءة RGB: تأثيرات ضوئية مميزة تضفي لمسة جمالية على سيت اب الألعاب الخاص بك.\r\n\r\nأزرار سريعة الاستجابة: توفر نقرات حاسمة وعمراً افتراضياً طويلاً للأزرار.\r\n\r\nتصميم مريح (Ergonomic): صُممت لتناسب راحة اليد وتقلل الإجهاد أثناء الاستخدام المكثف.\r\n\r\nتوصيل سهل: تعمل بمجرد توصيلها (Plug and Play) ومتوافقة مع جميع أنظمة التشغيل.',65.00,NULL,NULL,30,5,'active','products/IXgxNu275nFXgbY7fcDGmRAg1XimRNOZBDcC2xpF.jpg',NULL,NULL,3,5,NULL,NULL,'2026-02-15 20:13:12','2026-03-29 17:44:20','USD',NULL,NULL,NULL),(8,'7800X3D-5070',NULL,'Lenovo Legion Tower T5','Lenovo',4,'أقوى تجميعة قيمنق جاهزة من لينوفو: معالج Ryzen 7 7800X3D الأفضل عالمياً للألعاب،','قابلية التطوير: الجهاز مصمم بطريقة تسمح بتطوير الرام أو إضافة هاردسك إضافي بسهولة تامة مستقبلاً.','لمعالج (CPU): AMD Ryzen 7 7800X3D، المعالج المصنف كأفضل معالج ألعاب في العالم بفضل تقنية 3D V-Cache التي تمنحك استقراراً هائلاً في الفريمات كرت الشاشة RTX 5070 (12GB)، ورام 32GB DDR5. أداء يفوق التوقعات مع تبريد احترافي وشكل عصري',2350.00,NULL,NULL,19,5,'active','products/Wieqa5WE1Mou0QXFTyFNsDkN8JtnyPgyqjDGixlG.jpg',NULL,NULL,3,13,NULL,NULL,'2026-02-16 19:51:23','2026-03-29 17:44:20','USD',NULL,NULL,NULL),(9,'ROG-G22CH-i7-4060Ti',NULL,'Compact Gaming Desktop','Asus',3,'أقوى أداء في أصغر حجم: ASUS ROG Strix G22CH بمواصفات جبارة (i7 جيل 14 وRTX 4060 Ti). تصميم مدمج وأنيق يمنحك قوة الـ Desktop دون إشغال مساحة.','تنبيه للمشتري: هذا الجهاز يستهدف الزبائن الذين يقدرون \"التصميم والحجم الصغير\" مع الأداء العالي؛ فهو قطعة فنية تقنية أكثر من كونه مجرد كمبيوتر','المعالج (CPU): Intel Core i7-14700F من الجيل الرابع عشر، بـ 20 نواة لتقديم أداء خارق في الألعاب والمهام المتعددة.\r\n\r\nكرت الشاشة (GPU): NVIDIA GeForce RTX 4060 Ti بسعة 8GB، يدعم تقنيات تتبع الأشعة وDLSS 3 لتجربة لعب سلسة جداً.\r\n\r\nالذاكرة (RAM): 16GB من نوع DDR5 الأحدث، لسرعة استجابة فائقة.\r\n\r\nالتخزين: 1TB SSD NVMe فائق السرعة لتحميل الألعاب في ثوانٍ.\r\n\r\nنظام التبريد: نظام تبريد سائل أو هوائي متطور (حسب النسخة) مصمم خصيصاً للمساحات الصغيرة لضمان استقرار الأداء.\r\n\r\nالإضافات: يأتي مع لوحة مفاتيح وماوس ألعاب، وجاهز للعمل بنظام Windows 11 Home.',1999.00,NULL,NULL,6,5,'active','products/GmzOOBMY3NVeJsi7MlMpgyh7wm7evgPOWM5WGD2F.jpg',NULL,NULL,3,11,NULL,NULL,'2026-02-16 20:02:37','2026-03-29 17:44:20','USD',NULL,NULL,NULL),(10,'MSI-G275QF-180HZ',NULL,'Gaming Monitor','MSI',5,'شاشة MSI G275QF المخصصة للألعاب: قياس 27 بوصة، دقة QHD (2K)، تردد 180Hz، وزمن استجابة فائق السرعة 0.5ms. ألوان IPS مذهلة وتجربة لعب بدون تقطيع','إضاءة Aura Sync: يدعم الجهاز إضاءة RGB قابلة للتخصيص بالكامل لتتناسب مع باقي ملحقاتك','المعالج (CPU): Intel Core i7-14700F من الجيل الرابع عشر، بـ 20 نواة لتقديم أداء خارق في الألعاب والمهام المتعددة.\r\n\r\nكرت الشاشة (GPU): NVIDIA GeForce RTX 4060 Ti بسعة 8GB، يدعم تقنيات تتبع الأشعة وDLSS 3 لتجربة لعب سلسة جداً.\r\n\r\nالذاكرة (RAM): 16GB من نوع DDR5 الأحدث، لسرعة استجابة فائقة.\r\n\r\nالتخزين: 1TB SSD NVMe فائق السرعة لتحميل الألعاب في ثوانٍ.\r\n\r\nنظام التبريد: نظام تبريد سائل أو هوائي متطور (حسب النسخة) مصمم خصيصاً للمساحات الصغيرة لضمان استقرار الأداء.\r\n\r\nالإضافات: يأتي مع لوحة مفاتيح وماوس ألعاب، وجاهز للعمل بنظام Windows 11 Home.',280.00,NULL,NULL,8,5,'active','products/ZDuyTM24ebCybr4RkH5zkocRajWwk5icoeRZm0Ds.jpg',NULL,NULL,3,9,NULL,NULL,'2026-02-16 20:13:15','2026-03-29 17:44:20','USD',NULL,NULL,NULL),(13,'(SKU): ASUS-TUF-2025-F16',NULL,'ASUS TUF Gaming F16 (2025) - Core i7-13th Gen',NULL,3,'لابتوب جيمنج من الفئة العليا، معالج Intel Core i7 الجيل 13، كرت شاشة RTX 4060، وشاشة بدقة FHD+ وتردد 165Hz',NULL,'استمتع بأداء استثنائي مع ASUS TUF Gaming F16 موديل 2025. الجهاز مصمم لتحمل أقسى ظروف الاستخدام (Military-Grade Toughness).\r\nالمواصفات التقنية:\r\n\r\nالمعالج: Intel Core i7-13650HX.\r\n\r\nكرت الشاشة: NVIDIA GeForce RTX 4060 (8GB GDDR6).\r\n\r\nالذاكرة: 16GB DDR5 RAM.\r\n\r\nالتخزين: 1TB NVMe SSD.\r\n\r\nالتبريد: نظام Arc Flow Fans المطور.\r\nضمان وكيل معتمد لمدة عام كامل.',1470.00,1300.00,1600.00,5,1,'active',NULL,NULL,NULL,3,15,1,'years','2026-04-07 17:57:33','2026-04-07 17:57:33','USD','16 Inch Screen','أو رمادي ميكانيكي','صنعاء'),(14,'MSI-G275QF-180HZ25',NULL,'عربة أطفال',NULL,2,'عالي الجودة',NULL,'جميل جدا',12.00,3.00,10.00,5,1,'active',NULL,NULL,NULL,3,15,2,'years','2026-04-08 09:12:39','2026-04-08 09:12:39','SAR','16 Inch Screen','ازرق','صنعاء'),(15,'MSI-G275QF-180HZ24',NULL,'عربة أطفال كهربائية',NULL,2,'عالي الجودة بسعر منافس',NULL,'جميل جدا',12.00,3.00,10.00,5,1,'active',NULL,NULL,NULL,3,15,2,'years','2026-04-08 09:13:46','2026-04-08 09:13:46','SAR','16 Inch Screen','ازرق','صنعاء');
